import {createChallenge,stepChallenge,awardAnswer,scoreRun,rocketPose} from './rally-rules.js?v=3.1.0';
const courses=baseCourses.map((course,i)=>({...course,...THEMES[i],region:REGION_ROUTES[i]}));
import {initialState,stepCar,recoverCar,createDemoDriver} from './rally-physics.js?v=3.1.0';
import {World} from './rally-world.js?v=3.1.0';
import {RaceAudio} from './rally-audio.js';
import {prepareHospitalWorld} from './hso-world.js?v=3.1.0';
import {mountHospitalUI} from './hso-ui.js?v=3.1.0';
