function updateMap(){if(!track)return;const c=$('#minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height;
 if(!mapCache){const layer=document.createElement('canvas');layer.width=w;layer.height=h;const bg=layer.getContext('2d'),ps=track.samples;let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const {p} of ps){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);}const scale=Math.min((w-36)/(maxX-minX),(h-25)/(maxZ-minZ)),map=p=>[(p.x-(minX+maxX)/2)*scale+w/2,h-13-(maxZ-p.z)*scale];bg.lineCap='round';bg.lineJoin='round';bg.beginPath();ps.forEach((p,i)=>{const [x,y]=map(p.p);if(i===0)bg.moveTo(x,y);else bg.lineTo(x,y);});bg.strokeStyle='#729b9d80';bg.lineWidth=5;bg.stroke();bg.strokeStyle='#dcf6df';bg.lineWidth=1.5;bg.stroke();for(const s of track.checkpoints){const [x,y]=map(track.at(s).p);bg.fillStyle='#79e7c5';bg.fillRect(x-3,y-3,6,6);}mapCache={layer,map};}
 ctx.clearRect(0,0,w,h);ctx.drawImage(mapCache.layer,0,0);const [x,y]=mapCache.map(track.position(car.s,car.x));ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle='#caffea';ctx.fill();ctx.strokeStyle='#102738';ctx.lineWidth=2;ctx.stroke();
}
function updateHUD(){if(!track)return;$('#time').textContent=formatTime(car.time);$('#speed').textContent=Math.round((mode==='finish'?0:car.speed)*3.6);$('#boost-value').textContent=Math.floor(car.boost);$('#boost-fill').style.width=car.boost+'%';$('#progress-fill').style.width=(car.s/track.length*100)+'%';$('#checkpoint-status').textContent=`ARKIVPORT ${car.checkpoint} / 3`;$('#elevation').textContent=Math.round(track.at(car.s).p.y)+' MOH';$('#distance').textContent=`${(car.s/1000).toFixed(1)} / ${(track.length/1000).toFixed(1)} KM`;$('#drive-status').textContent=mode==='finish'?'ARKIVRAKETTEN · KARRIEREOPPSKYTING':car.turbo>0?'EKSPERTTURBO · '+car.turbo.toFixed(1)+' S':car.stagger>0?'USTØ · FARTSTAP':car.boosting?'BOOST AKTIV':car.air>.2?'SVEV':car.drift>.3?'DRIFT · RETT OPP FOR GREP':car.speed<2?'HOLD W ELLER ↑ FOR GASS':'FINN FLYTEN';document.body.classList.toggle('boosting',car.boosting);document.body.classList.toggle('turbo',car.turbo>0);if(quizState)$('#quiz-time').style.width=(clamp(quizState.left/quizState.duration,0,1)*100)+'%';const incoming=encounters.find(e=>e.phase==='warning');$('#mascot-alert').classList.toggle('hidden',!incoming||mode!=='race');if(incoming)$('#mascot-alert').textContent=mascotNames[incoming.kind]+' ↓  '+Math.max(0,Math.round(incoming.s-car.s))+' m · SVING UNNA RINGEN';updateMap();updateRallyUI(challenge,car,mode,finishAge);}
function readInput(){let steer=(keys.KeyD||keys.ArrowRight||touch.right?1:0)-(keys.KeyA||keys.ArrowLeft||touch.left?1:0),throttle=Number(!!(keys.KeyW||keys.ArrowUp||touch.throttle)),brake=Number(!!(keys.KeyS||keys.ArrowDown||touch.brake)),boost=!!(keys.ShiftLeft||keys.ShiftRight||touch.boost),drift=!!(keys.Space||touch.drift),fire=!!(keys.KeyE||touch.fire);
 const pad=navigator.getGamepads?.()?.find(p=>p&&p.connected);if(pad){const axis=pad.axes[0]||0;if(Math.abs(axis)>.12)steer=axis;throttle=Math.max(throttle,pad.buttons[7]?.value||0);brake=Math.max(brake,pad.buttons[6]?.value||0);fire ||= !!pad.buttons[5]?.pressed;boost ||= !!pad.buttons[0]?.pressed;drift ||= !!pad.buttons[2]?.pressed;const pressed=i=>pad.buttons[i]?.pressed&&!padWas[i];if(mode==='quiz'){if(pressed(0))answerQuiz(0);if(pressed(2))answerQuiz(1);if(pressed(1))answerQuiz(2);}else if(mode==='race'){if(pressed(1)){recoverCar(car,track);resetInterpolation();world.cameraInitialized=false;toast('TILBAKE VED PORTEN · +3 SEK');}if(pressed(3))startRace();}if(pressed(9)){if(mode==='paused')closeModal();else pause();}padWas=pad.buttons.map(b=>b.pressed);}if(raceSettings.autogas&&['race','quiz'].includes(mode)&&!brake)throttle=true;return {steer,throttle,brake,boost,drift,fire};}
function step(dt,input){if(raceDemo&&mode==='race'){input=demoDriver(car,track,raceSettings.assist);if(raceSettings.sightseeing){input.fire=false;input.boost=false;input.throttle=car.speed<30;input.brake=car.speed>32;}}let effective=dt;if(mode==='quiz'){quizState.left-=dt;if(raceDemo&&quizState.left<quizState.duration-2&&!quizState.answered)answerQuiz(quizState.q.correct);if(!quizState.answered){if(quizState.left<=0)answerQuiz(null);}else{quizState.after-=dt;if(quizState.after<=0)closeQuiz();}return;}
 const before={s:car.s,x:car.x,air:car.air},events=stepCar(car,input,effective,track,raceSettings);
 for(const event of stepChallenge(challenge,car,before,input,effective,{assist:raceSettings.assist})){
  if(event.type==='water')audio.cue('water');else if(event.type==='splash')audio.cue('splash');else if(event.type==='troll-cleared'){audio.cue('correct');toast('UNNSKYLDNING BORTSPYLT · +'+event.juice+' JUICE',1.6);}
  else if(event.type==='troll-bump'){audio.cue('crash');toast('TROLLET BREMSET DEG · BRUK VANN ELLER SVING UNNA',1.8);}
 }
 director.step(car,effective);
 if(mode==='race'&&raceSettings.quiz)for(const event of stepEncounters(encounters,car,before,effective,track)){
  if(event.type==='warning'){audio.cue('checkpoint');toast(mascotNames[event.encounter.kind]+' SLIPPER EN PAKKE!',2);}
  else if(event.type==='hit'){audio.cue('crash');openQuiz(0,event.encounter);}
  else{dodges++;audio.cue('menu');toast('UNNA! · GODT LINJEVALG',1.8);}
 }
 if(car.time>=recordAt){recording.push([+car.time.toFixed(3),+car.s.toFixed(3),+car.x.toFixed(3),+car.heading.toFixed(4),+car.air.toFixed(3)]);recordAt=car.time+.08;}
 for(const e of events){if(e==='checkpoint'){director.checkpoint(car.time);audio.cue('checkpoint');toast(`ARKIVPORT ${car.checkpoint} / 3`);const reference=ghostFrames?.find(f=>f[1]>=track.checkpoints[car.checkpoint-1]);if(reference){const delta=car.time-reference[0];$('#split').textContent=`${delta>0?'+':'−'}${Math.abs(delta).toFixed(2)} s ${delta>0?'BAK':'FORAN'} ${ghostLabel}`;$('#split').style.color=delta>0?'#ffc8a6':'#90ffe1';}if(raceSettings.quiz)openQuiz(car.checkpoint);}else if(e==='finish'){finishRace();break;}else if(e==='crash'){audio.cue('crash');toast('BREMS INN. AKSELERER UT.',1.6);}else if(e==='pad'){audio.cue('correct');toast('BOOSTFELT · +25 %',1.6);}else if(e==='jump'){audio.cue('jump');toast('UT I DET BLÅ',1.5);}}
}
function updateGhost(renderTime=car.time){if(!ghostFrames?.length||!['race','quiz'].includes(mode)){world.setGhost(null);return;}while(ghostIndex<ghostFrames.length-2&&ghostFrames[ghostIndex+1][0]<renderTime)ghostIndex++;const a=ghostFrames[ghostIndex],b=ghostFrames[Math.min(ghostIndex+1,ghostFrames.length-1)],t=clamp((renderTime-a[0])/(b[0]-a[0]||1),0,1);if(renderTime>b[0]+.25){world.setGhost(null);return;}let v=i=>a[i]+(b[i]-a[i])*t;world.setGhost({s:v(1),x:v(2),heading:v(3),air:v(4)});}
function frame(now){const raw=(now-lastFrame)/1000;lastFrame=now;const dt=Math.min(raw,.05);if(raw>0&&raw<.5)frameAverage+=(raw-frameAverage)*.03;/* Background pauses are handled by blur/visibility; slow GPU frames must not lock the controls. */director.gamepadMenu(mode,dt);const input=readInput();if(mode==='countdown'){countdown-=Math.min(raw,.25);let n=Math.ceil(countdown);if(n!==lastCount&&n>0){lastCount=n;audio.cue('countdown');}$('#countdown').textContent=n>0?n:'KJØR';if(countdown<=0){mode='race';$('#countdown').textContent='';audio.cue('go');toast(raceDemo?'DEMOTUR · SE BREMSING OG LINJEVALG':'HOLD W · FINN LINJEN',2.8);}}else if(mode==='race'||mode==='quiz'){accumulator+=dt;let steps=0;while(accumulator>=fixedStep&&steps++<10&&['race','quiz'].includes(mode)){previousCar={...car};step(fixedStep,input);accumulator-=fixedStep;}}else accumulator=0;if(mode==='finish'||mode==='results'){finishAge+=dt;if(mode==='finish'&&finishAge>=13.2)setMode('results');}
 if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}const display=['race','quiz'].includes(mode)?interpolateState(previousCar,car,accumulator/fixedStep,track):['finish','results'].includes(mode)?rocketPose(car,finishAge,track,challenge?.juice||0):car;updateGhost(display.time);world.render(display,dt,mode,{camera:settings.camera,motion:settings.motion,encounters:raceSettings.quiz?encounters:[],challenge});audio.update({speed:car.speed*3.6,throttle:raceDemo?car.speed>0:input.throttle,boost:car.boosting,drift:car.drift,active:['race','quiz'].includes(mode)},dt);director.update(car,track,mode,dt,settings.coaching);hudAccumulator+=dt;if(hudAccumulator>.06){hudAccumulator=0;updateHUD();}requestAnimationFrame(frame);}
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{});}
