 $('#play-btn').onclick=()=>{if(!saved.seenHelp){saved.seenHelp=true;help();}else startRace();};$('#help-btn').onclick=help;$('#settings-btn').onclick=()=>settingsModal();$('#sources-btn').onclick=()=>sourcesModal();$('#leaderboard-btn').onclick=()=>leaderboard.display();$('#touch-recover').onclick=()=>{if(mode==='race'){recoverCar(car,track);resetInterpolation();world.cameraInitialized=false;toast('TILBAKE VED PORTEN · +3 SEK');}};$('#close-modal').onclick=()=>closeModal();$('#pause-btn').onclick=pause;$('#skip-quiz').onclick=()=>{if(quizState?.answered){quizState.after=0;}else if(!quizState?.encounter)answerQuiz(null);};$('#retry-btn').onclick=startRace;$('#menu-btn').onclick=toMenu;$('#next-btn').onclick=()=>{if(raceDemo){startRace();return;}if(trackIndex===2){toMenu();return;}selectCourse(trackIndex+1);startRace();};$('#review-btn').onclick=()=>sourcesModal(true);$$('.fullscreen').forEach(b=>b.onclick=fullscreen);
 window.addEventListener('keydown',e=>{if(e.target?.closest('input,textarea,select,[contenteditable=true]')){if(e.code==='Escape'&&!$('#modal-backdrop').classList.contains('hidden'))closeModal();return;}const modalOpen=!$('#modal-backdrop').classList.contains('hidden'),interactive=/^(BUTTON|INPUT|SELECT|TEXTAREA|A)$/.test(e.target?.tagName||document.activeElement?.tagName||'');if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&!modalOpen&&!interactive&&['race','quiz','countdown'].includes(mode))e.preventDefault();if(modalOpen){if(e.code==='Escape'){e.preventDefault();closeModal();}if(e.code==='Tab'){const focusable=$$('#modal button:not(:disabled),#modal a,#modal input,#modal select'),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(interactive&&['Enter','Space'].includes(e.code))return;keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP'){pause();return;}if(e.code==='KeyF')fullscreen();if(e.code==='KeyC'){settings.camera=settings.camera==='chase'?'hood':'chase';world.cameraInitialized=false;}if(mode==='quiz'&&/^Digit[123]$/.test(e.code)){answerQuiz(+e.code.slice(-1)-1);return;}if(['race','quiz','countdown','finish','results'].includes(mode)&&e.code==='KeyR')startRace();if(mode==='race'&&e.code==='Enter'&&!interactive){recoverCar(car,track);resetInterpolation();world.cameraInitialized=false;toast('TILBAKE VED PORTEN · +3 SEK');}if(mode==='menu'&&e.code==='Enter'&&!interactive)$('#play-btn').click();});window.addEventListener('keyup',e=>{keys[e.code]=false;});window.addEventListener('blur',()=>{keys={};touch={};pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();audio.suspend();}else if(mode==='menu')audio.start();});
